import java.util.Scanner;

interface Speaker {
    void speak();
}

interface Walker {
    void walk(int laps);
}

class Cat implements Speaker, Walker {
    String name;

    Cat(String name) {
        this.name = name;
    }

    @Override
    public void speak() {
        System.out.println(name + "：喵～");
    }

    @Override
    public void walk(int laps) {
        for (int i = 0; i < laps; i++) {
            System.out.println(name + "绕鱼塘走了一圈");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int laps = sc.nextInt();
        Cat c = new Cat("{cat}");
        Speaker s = c;
        Walker w = c;
        s.speak();
        w.walk(laps);
    }
}
